@Override
	public void renderParticle(BufferBuilder buffer, Entity viewer, float partialTicks, float rotationX, float rotationZ,
			float rotationYZ, float rotationXY, float rotationXZ){

		// Copied from ParticleWizardry, needs to be here since we're not calling super
		updateEntityLinking(viewer, partialTicks);

		GlStateManager.pushMatrix();
		GlStateManager.pushAttrib();

		GlStateManager.enableBlend();
		GlStateManager.disableAlpha();
		GlStateManager.disableCull();
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		// Makes the particle colour add to the colour of the texture pixels, rather than the default multiplying
		GlStateManager.glTexEnvi(GL11.GL_TEXTURE_ENV, GL11.GL_TEXTURE_ENV_MODE, GL11.GL_ADD);

		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		// Does the texture translation wrapping thing (the cool stuff)
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();

		GlStateManager.translate((this.particleAge + partialTicks)/(float)this.particleMaxAge * -2, 0, 0);

		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		RenderHelper.disableStandardItemLighting();

		Minecraft.getMinecraft().getTextureManager().bindTexture(TEXTURE);

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_TEX_COLOR);

		float x = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float y = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float z = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		// Increases from 0 to 1 in steps of 0.125 evenly throughout the particle's lifetime
		float f = 0.875f - 0.125f * MathHelper.floor((float)this.particleAge/(float)this.particleMaxAge * 8 - 0.000001f);
		float g = f + 0.125f;
		float hrepeat = 1;
		float scale = 0.6f;
		float yScale = 0.7f * scale;
		float dx = mirror ? -scale : scale;
		float dz = scale;

		buffer.pos(x-dx, y-yScale, z-dz).tex(0, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y+yScale, z-dz).tex(0, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y-yScale, z-dz).tex(0.25*hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y+yScale, z-dz).tex(0.25*hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y-yScale, z+dz).tex(0.5*hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x+dx, y+yScale, z+dz).tex(0.5*hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y-yScale, z+dz).tex(0.75*hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y+yScale, z+dz).tex(0.75*hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y-yScale, z-dz).tex(hrepeat, g).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();
		buffer.pos(x-dx, y+yScale, z-dz).tex(hrepeat, f).color(particleRed, particleGreen, particleBlue, particleAlpha).endVertex();

		Tessellator.getInstance().draw();

		// Undoes the texture transformations
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		GlStateManager.disableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.enableCull();
		GlStateManager.enableLighting();
		// Reverses the colour addition change from before
		GlStateManager.glTexEnvi(GL11.GL_TEXTURE_ENV, GL11.GL_TEXTURE_ENV_MODE, GL11.GL_MODULATE);

		GlStateManager.popAttrib();
		GlStateManager.popMatrix();

	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity viewer, float partialTicks, float rotationX, float rotationZ, float rotationYZ,
			float rotationXY, float rotationXZ){

		// Copied from ParticleWizardry, needs to be here since we're not calling super
		updateEntityLinking(viewer, partialTicks);

		float x = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks);
		float y = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks);
		float z = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks);

		// Translates the particle a short distance in front of the entity
		if(this.entity != null && this.shouldApplyOriginOffset()){
			if(this.entity != viewer || Minecraft.getMinecraft().gameSettings.thirdPersonView != 0){
				Vec3d look = entity.getLook(partialTicks).scale(THIRD_PERSON_AXIAL_OFFSET);
				x += look.x;
				y += look.y;
				z += look.z;
			}
		}

		if(this.target != null){

			this.targetX = this.target.prevPosX + (this.target.posX - this.target.prevPosX) * partialTicks;
			double correction = this.target.posY - this.target.posY;
			this.targetY = this.target.prevPosY + (this.target.posY - this.target.prevPosY) * partialTicks
					+ target.height/2 + correction;
			this.targetZ = this.target.prevPosZ + (this.target.posZ - this.target.prevPosZ) * partialTicks;

		}else if(this.entity != null && this.length > 0){

			Vec3d look = entity.getLook(partialTicks).scale(length);
			this.targetX = x + look.x;
			this.targetY = y + look.y;
			this.targetZ = z + look.z;
		}

		if(Double.isNaN(targetX) || Double.isNaN(targetY) || Double.isNaN(targetZ)){
			Wizardry.logger.warn("Attempted to render a targeted particle, but neither its target entity nor target"
					+ "position was set, and it either had no length assigned or was not linked to an entity!");
			return;
		}

		GlStateManager.pushMatrix();
		GlStateManager.translate(x - interpPosX, y - interpPosY, z - interpPosZ);

		double dx = this.targetX - x;
		double dy = this.targetY - y;
		double dz = this.targetZ - z;

		// No need for previous tick target positions and all that stuff since this is the only place they're used
		// and interpolating like this works just as well
		if(!Double.isNaN(targetVelX) && !Double.isNaN(targetVelY) && !Double.isNaN(targetVelZ)){
			dx += partialTicks * this.targetVelX;
			dy += partialTicks * this.targetVelY;
			dz += partialTicks * this.targetVelZ;
		}

		// The distance from origin to endpoint
		double length = Math.sqrt(dx*dx+dy*dy+dz*dz);

		// Math.atan2 computes within -180 to +180, rather than -90 to +90.
		float yaw = (float)(180d/Math.PI * Math.atan2(dx, dz));
		float pitch = (float)(180f/(float)Math.PI * Math.atan(-dy/Math.sqrt(dz*dz+dx*dx)));

		GL11.glRotatef(yaw, 0, 1, 0);
		GL11.glRotatef(pitch, 1, 0, 0);

		Tessellator tessellator = Tessellator.getInstance();

		this.draw(tessellator, length, partialTicks);

		GlStateManager.popMatrix();
	}

@Override
	protected void draw(Tessellator tessellator, double length, float partialTicks){

		random.setSeed(seed); // Reset the random so we get the same sequence of numbers each frame

		float scale = this.particleScale;

		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		// Hmmmm we can't get the texture to tile using OpenGL texture space because it's on a sprite sheet...
		// Solution: Draw loads of boxes. Simple!
		// (Since there aren't going to be that many of these particles around we could have not used sprite sheets
		// and done the OpenGL texture space thing, but this is kinda easier)
		// Everything is drawn back-to-front so it looks like the vine is growing from the origin, not the endpoint
		int i = 0;
		while(i + SEGMENT_LENGTH < length){
			drawShearedBox(tessellator, 0, 0, length-i, 0, 0, length-i-SEGMENT_LENGTH, THICKNESS * scale,
					particleRed, particleGreen, particleBlue, particleAlpha);
			i += SEGMENT_LENGTH;
		}

		drawShearedBox(tessellator, 0, 0, length-i, 0, 0, 0, THICKNESS * scale,
				particleRed, particleGreen, particleBlue, particleAlpha);

		for(double l=length; l>0; l-=LEAF_SPACING){

			GlStateManager.pushMatrix();

			GlStateManager.rotate(random.nextInt(4) * 90, 0, 0, 1);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

			TextureAtlasSprite leaf = Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite(
					LEAF_TEXTURES[random.nextInt(LEAF_TEXTURES.length)].toString());

			float w = 16 * THICKNESS * scale;
			float u1 = leaf.getMinU();
			float u2 = leaf.getMaxU();
			float v1 = leaf.getMinV();
			float v2 = leaf.getMaxV();

			float colourVariation = 0.3f;

			float r = MathHelper.clamp(particleRed + (random.nextFloat() - 0.5f) * colourVariation, 0, 1);
			float g = MathHelper.clamp(particleGreen + (random.nextFloat() - 0.5f) * colourVariation, 0, 1);
			float b = MathHelper.clamp(particleBlue + (random.nextFloat() - 0.5f) * colourVariation, 0, 1);

			buffer.pos(0, 0, l).tex(u1, v1).color(r, g, b, particleAlpha).endVertex();
			buffer.pos(w, 0, l).tex(u2, v1).color(r, g, b, particleAlpha).endVertex();
			buffer.pos(w, w, l).tex(u2, v2).color(r, g, b, particleAlpha).endVertex();
			buffer.pos(0, w, l).tex(u1, v2).color(r, g, b, particleAlpha).endVertex();

			tessellator.draw();

			GlStateManager.popMatrix();
		}

		// Makes the rain go weird
		//GlStateManager.enableLighting();
	}

@Override
	public void doRender(EntityForceArrow arrow, double par2, double par4, double par6, float par8, float par9){

		this.bindEntityTexture(arrow);
		GlStateManager.pushMatrix();
		GlStateManager.disableLighting();
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);

		GlStateManager.translate((float)par2, (float)par4, (float)par6);
		GlStateManager.rotate(arrow.prevRotationYaw + (arrow.rotationYaw - arrow.prevRotationYaw) * par9 - 90.0F, 0.0F,
				1.0F, 0.0F);
		GlStateManager.rotate(arrow.prevRotationPitch + (arrow.rotationPitch - arrow.prevRotationPitch) * par9, 0.0F,
				0.0F, 1.0F);
		GlStateManager.rotate(180, 0, 1, 0);
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();
		float pixel = 1.0f / 32.0f;
		float u1 = 0.0f;
		float u2 = pixel * 14;
		float v1 = 0.0f;
		float v2 = pixel * 7;
		float u3 = pixel * 16;
		float u4 = 1.0f;
		float v3 = 0.0f;
		float v4 = pixel * 16;
		float u5 = 0.0f;
		float u6 = pixel * 7;
		float v5 = pixel * 25;
		float v6 = 1.0f;
		float scale = 0.05625F;
		float f11 = 0.0f;
		GlStateManager.enableRescaleNormal();
		// f11 = (float)par1EntityArrow.arrowShake - par9;
		if(f11 > 0.0F){
			float f12 = -MathHelper.sin(f11 * 3.0F) * f11;
			GlStateManager.rotate(f12, 0.0F, 0.0F, 1.0F);
		}

		scale *= 0.8f;

		GlStateManager.rotate(45.0F, 1.0F, 0.0F, 0.0F);
		GlStateManager.scale(scale, scale, scale);
		GlStateManager.translate(-4.0F, 0.0F, 0.0F);

		// Front
		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
		buffer.pos(-5, 3.5, -3.5).tex((double)u5, (double)v5).endVertex();
		buffer.pos(-5, 3.5, 3.5).tex((double)u6, (double)v5).endVertex();
		buffer.pos(-5, -3.5, 3.5).tex((double)u6, (double)v6).endVertex();
		buffer.pos(-5, -3.5, -3.5).tex((double)u5, (double)v6).endVertex();
		tessellator.draw();

		// Back
		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
		buffer.pos(-5, -3.5, -3.5).tex((double)u5, (double)v6).endVertex();
		buffer.pos(-5, -3.5, 3.5).tex((double)u6, (double)v6).endVertex();
		buffer.pos(-5, 3.5, 3.5).tex((double)u6, (double)v5).endVertex();
		buffer.pos(-5, 3.5, -3.5).tex((double)u5, (double)v5).endVertex();
		tessellator.draw();

		// Rings
		for(int i = 0; i < 5; i++){
			GlStateManager.color(1, 1, 1, 1 - i * 0.2f);
			double j = i + ((double)arrow.ticksExisted % 3) / 3;
			double width = 2.0d + (Math.sqrt(j * 2) - 0.6) * 2;
			GL11.glNormal3f(scale, 0.0F, 0.0F);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-10 + j * 4, -width, -width).tex((double)u3, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, -width, width).tex((double)u4, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, width, width).tex((double)u4, (double)v4).endVertex();
			buffer.pos(-10 + j * 4, width, -width).tex((double)u3, (double)v4).endVertex();
			tessellator.draw();
			GL11.glNormal3f(-scale, 0.0F, 0.0F);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-10 + j * 4, width, -width).tex((double)u3, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, width, width).tex((double)u4, (double)v3).endVertex();
			buffer.pos(-10 + j * 4, -width, width).tex((double)u4, (double)v4).endVertex();
			buffer.pos(-10 + j * 4, -width, -width).tex((double)u3, (double)v4).endVertex();
			tessellator.draw();
		}

		GlStateManager.color(1, 1, 1, 1);

		// Sides
		for(int i = 0; i < 4; ++i){
			GlStateManager.rotate(90.0F, 1.0F, 0.0F, 0.0F);
			GL11.glNormal3f(0.0F, 0.0F, scale);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);
			buffer.pos(-10.0D, -4.0D, 0.0D).tex((double)u1, (double)v1).endVertex();
			buffer.pos(10.0D, -4.0D, 0.0D).tex((double)u2, (double)v1).endVertex();
			buffer.pos(10.0D, 4.0D, 0.0D).tex((double)u2, (double)v2).endVertex();
			buffer.pos(-10.0D, 4.0D, 0.0D).tex((double)u1, (double)v2).endVertex();
			tessellator.draw();
		}

		GlStateManager.disableBlend();

		GlStateManager.disableRescaleNormal();
		GlStateManager.enableLighting();
		GlStateManager.popMatrix();
	}

public static void SHAPE_BEAM(World world, Vec3d target, Vec3d origin, Color color) {
		ParticleBuilder beam = new ParticleBuilder(10);
		beam.setRender(new ResourceLocation(Wizardry.MODID, MISC.SPARKLE_BLURRED));
		beam.setAlphaFunction(new InterpFloatInOut(0.3f, 1f));
		//beam.disableRandom();

		beam.setColor(ColorUtils.shiftColorHueRandomly(color, 10));
		beam.setCollision(true);

		Vec3d look = target.subtract(origin).normalize();
		double dist = target.distanceTo(origin);

		ParticleSpawner.spawn(beam, world, new StaticInterp<>(origin), 1, 0, (aFloat1, particleBuilder1) -> {
			particleBuilder1.setPositionOffset(look.scale(RandUtil.nextDouble(0, dist)));
			particleBuilder1.setScale(RandUtil.nextFloat(0.1f, 0.5f));
			final int life = RandUtil.nextInt(50, 60);
			particleBuilder1.setLifetime(life);
			particleBuilder1.enableMotionCalculation();
			particleBuilder1.setCollision(true);
			particleBuilder1.setCanBounce(true);
			particleBuilder1.setAcceleration(new Vec3d(0, -0.03, 0));

			double radius = 2;
			double theta = 2.0f * (float) Math.PI * RandUtil.nextFloat();
			double r = radius * RandUtil.nextFloat();
			double x = r * MathHelper.cos((float) theta);
			double z = r * MathHelper.sin((float) theta);
			Vec3d dest = new Vec3d(x, RandUtil.nextDouble(-1, 2), z);
			particleBuilder1.setPositionFunction(new InterpBezier3D(Vec3d.ZERO, dest, dest.scale(2), new Vec3d(dest.x, RandUtil.nextDouble(-2, 2), dest.z)));

			particleBuilder1.setTick(particle -> {
				if (particle.getAge() >= particle.getLifetime() / RandUtil.nextDouble(2, 5)) {
					if (particle.getAcceleration().y == 0)
						particle.setAcceleration(new Vec3d(0, RandUtil.nextDouble(-0.05, -0.01), 0));
				} else if (particle.getAcceleration().x != 0 || particle.getAcceleration().y != 0 || particle.getAcceleration().z != 0) {
					particle.setAcceleration(Vec3d.ZERO);
				}
			});
		});

		ParticleSpawner.spawn(beam, world, new StaticInterp<>(origin), 10, 0, (aFloat, particleBuilder) -> {
			particleBuilder.setTick(particle -> particle.setAcceleration(Vec3d.ZERO));

			particleBuilder.setScaleFunction(new InterpFloatInOut(0, 1f));
			particleBuilder.setAlphaFunction(new InterpFloatInOut(0.3f, 0.2f));
			particleBuilder.setScale(RandUtil.nextFloat(0.5f, 1.5f));
			particleBuilder.setLifetime(RandUtil.nextInt(10, 20));
			particleBuilder.disableMotionCalculation();
			particleBuilder.setMotion(Vec3d.ZERO);
			particleBuilder.setCanBounce(false);
			particleBuilder.setPositionOffset(Vec3d.ZERO);
			particleBuilder.setPositionFunction(new InterpLine(Vec3d.ZERO, target.subtract(origin)));
		});
	}

@Override
	public void doRenderLayer(@Nonnull EntityLivingBase entitylivingbaseIn, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		if (BaublesSupport.getItem(entitylivingbaseIn, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO).isEmpty())
			return;
		ItemStack halo = BaublesSupport.getItem(entitylivingbaseIn, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO);

		// TODO: Remove these once we have a cosmetics system
		if (halo.getItem() == ModItems.FAKE_HALO && !ClientConfigValues.renderCrudeHalo) return;
		if (halo.getItem() == ModItems.REAL_HALO && !ClientConfigValues.renderRealHalo) return;
		if (halo.getItem() == ModItems.CREATIVE_HALO && !ClientConfigValues.renderCreativeHalo) return;

		if (halo.getItem() == ModItems.FAKE_HALO) {
			GlStateManager.pushMatrix();

			if (entitylivingbaseIn.isSneaking()) GlStateManager.translate(0.0f, 0.2f, 0.0f);

			boolean flag = entitylivingbaseIn instanceof EntityVillager || entitylivingbaseIn instanceof EntityZombieVillager;

			if (entitylivingbaseIn.isChild() && !(entitylivingbaseIn instanceof EntityVillager)) {
				GlStateManager.translate(0.0f, 0.5f * scale, 0.0f);
				GlStateManager.scale(0.7f, 0.7f, 0.7f);
				GlStateManager.translate(0.0f, 16.0f * scale, 0.0f);
			}

			if (flag) GlStateManager.translate(0.0f, 0.1875f, 0.0f);

			this.modelRenderer.postRender(0.0625f);
			GlStateManager.color(1.0f, 1.0f, 1.0f, 1.0f);

			GlStateManager.translate(0.0f, -0.25f, 0.0f);
			GlStateManager.rotate(180.0f, 0.0f, 1.0f, 0.0f);
			GlStateManager.scale(0.625f, -0.625f, -0.625f);

			Minecraft.getMinecraft().getItemRenderer().renderItem(entitylivingbaseIn, halo, ItemCameraTransforms.TransformType.HEAD);

			GlStateManager.popMatrix();
		} else {
		    Entity entity = entitylivingbaseIn;

			Vec3d entityOrigin = entity.getPositionVector().add(0, entity.height + (entity.isSneaking() ? 0.2 : 0.4), 0);
			InterpCircle circle = new InterpCircle(Vec3d.ZERO, new Vec3d(0, 1, 0), 0.3f, RandUtil.nextFloat(), RandUtil.nextFloat());

			for (Vec3d origin : circle.list(5)) {
				RenderFunction baseRenderFunction = new RenderFunctionBasic(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED), false);
				ParticleBuilder glitter = new ParticleBuilder(3);
				glitter.setAlphaFunction(new InterpFloatInOut(1f, 1f));
				glitter.disableMotionCalculation();
				glitter.disableRandom();

				ParticleSpawner.spawn(glitter, entity.world, new StaticInterp<>(entityOrigin.add(origin)), 1, 0, (aFloat, particleBuilder) -> {
					if (RandUtil.nextInt(10) != 0)
						if (halo.getItem() == ModItems.CREATIVE_HALO)
							glitter.setColor(ColorUtils.changeColorAlpha(new Color(0xd600d2), RandUtil.nextInt(60, 100)));
						else glitter.setColor(ColorUtils.changeColorAlpha(Color.YELLOW, RandUtil.nextInt(60, 100)));
					else glitter.setColor(ColorUtils.changeColorAlpha(Color.WHITE, RandUtil.nextInt(60, 100)));
					glitter.setAlphaFunction(new InterpFloatInOut(0.5f, 0.5f));
					glitter.setLifetime(10);
					glitter.setScaleFunction(new InterpFloatInOut(0.5f, 0.5f));

					glitter.setRenderFunction(
							new RenderFunction(ParticleRenderManager.getLAYER_BLOCK_MAP_ADDITIVE()) {
								@Override
								public void render(float i,
												   @NotNull ParticleBase particle, @NotNull Color color, float alpha,
												   @NotNull BufferBuilder worldRendererIn, @Nullable Entity entityIn,
												   float partialTicks, float rotationX, float rotationZ,
												   float rotationYZ, float rotationXY, float rotationXZ,
												   float scale, float rotation, @NotNull Vec3d pos,
												   int skyLight, int blockLight) {

									Vec3d interpPos =
											new Vec3d(
//													ClientTickHandler.interpPartialTicks(entity.prevPosX, entity.posX) - Particle.interpPosX,
//													ClientTickHandler.interpPartialTicks(entity.prevPosY, entity.posY) - Particle.interpPosY,
//													ClientTickHandler.interpPartialTicks(entity.prevPosZ, entity.posZ) - Particle.interpPosZ
													entity.prevPosX + (entity.posX - entity.prevPosX) * ClientTickHandler.getPartialTicks() - Particle.interpPosX,
													entity.prevPosY + (entity.posY - entity.prevPosY) * ClientTickHandler.getPartialTicks() - Particle.interpPosY,
													entity.prevPosZ + (entity.posZ - entity.prevPosZ) * ClientTickHandler.getPartialTicks() - Particle.interpPosZ
											);
									Vec3d newPos = interpPos
											.add(0, entity.height + (entity.isSneaking() ? 0.2 : 0.4), 0)
											.add(origin);

									baseRenderFunction.render(i,
											particle, color, alpha,
											worldRendererIn, entityIn,
											partialTicks, rotationX, rotationZ,
											rotationYZ, rotationXY, rotationXZ,
											scale, rotation, newPos,
											skyLight, blockLight);
								}
							}
					);
				});
			}
		}
	}

private void renderSpinningCubes(PoseStack ms, MultiBufferSource buffers, int overlay, int cubes, int iters) {
		for (int curIter = iters; curIter > 0; curIter--) {
			final float modifier = 6F;
			final float rotationModifier = 0.2F;
			final float radiusBase = 0.35F;
			final float radiusMod = 0.05F;

			double ticks = ClientTickHandler.ticksInGame + ClientTickHandler.partialTicks - 1.3 * (iters - curIter);
			float offsetPerCube = 360 / cubes;

			ms.pushPose();
			ms.translate(-0.025F, 0.85F, -0.025F);
			for (int i = 0; i < cubes; i++) {
				float offset = offsetPerCube * i;
				float deg = (int) (ticks / rotationModifier % 360F + offset);
				float rad = VecHelper.toRadians(deg);
				float radiusX = (float) (radiusBase + radiusMod * Math.sin(ticks / modifier));
				float radiusZ = (float) (radiusBase + radiusMod * Math.cos(ticks / modifier));
				float x = (float) (radiusX * Math.cos(rad));
				float z = (float) (radiusZ * Math.sin(rad));
				float y = (float) Math.cos((ticks + 50 * i) / 5F) / 10F;

				ms.pushPose();
				ms.translate(x, y, z);
				float xRotate = (float) Math.sin(ticks * rotationModifier) / 2F;
				float yRotate = (float) Math.max(0.6F, Math.sin(ticks * 0.1F) / 2F + 0.5F);
				float zRotate = (float) Math.cos(ticks * rotationModifier) / 2F;

				ms.mulPose(new Quaternionf().rotateAxis(rad, xRotate, yRotate, zRotate));
				float alpha = 1;
				if (curIter < iters) {
					alpha = (float) curIter / (float) iters * 0.4F;
				}

				VertexConsumer buffer = buffers.getBuffer(curIter < iters ? RenderType.entityTranslucentCull(cubeTex) : RenderType.entitySolid(cubeTex));
				spinningCube.render(ms, buffer, 0xF000F0, overlay, 1, 1, 1, alpha);

				ms.popPose();
			}
			ms.popPose();
		}
	}
